import json
off = {r['phase']+':' + r['id']: r for r in [json.loads(l) for l in open('bench/results/2026-10-12/m1-ngram/replay/off-greedy/requests.jsonl')]}
A   = {r['phase']+':' + r['id']: r for r in [json.loads(l) for l in open('bench/results/2026-10-12/m1-ngram/replay/A-greedy/requests.jsonl')]}
from collections import Counter
phases = Counter()
for k in set(off):
    p = k.split(':')[0]
    phases[p] += 1
print('keys per phase (off):', dict(phases))
same=diff=0; per_phase={}
for p in ['single-agent','single-mem','dual-agent','dual-mem']:
    same_p=diff_p=0
    for k in off:
        if not k.startswith(p): continue
        if k not in A: continue
        o,a=off[k],A[k]
        if o['out_sha256']==a['out_sha256']:
            same_p+=1
        else:
            diff_p+=1
        same+=1; diff+=1
    per_phase[p]=(same_p,diff_p)
    print(p, 'same',same_p,'diff',diff_p)
print('TOTAL same/diff', same, diff)
"

